-- request: GET /api/places?select=id,location_x,location_y,location_num_points,location_num_geometries,location_point_on_surface,location_wkt,location_ewkt,location_is_empty,location_is_simple,location_xmin,location_ymin,location_xmax,location_ymax,mx:location_x(transform=3857),area_x,area_z,area_m,area_start_point,area_end_point,area_wkt(simplify=0.001)&order=id&limit=5
SELECT json_build_object('has_next', coalesce(bool_or(s1.__rn > $3), false), 'has_prev', false, 'first', (json_agg(s1.__key ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $3))->0, 'last', (json_agg(s1.__key ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $3))->-1, 'n', count(*) FILTER (WHERE s1.__rn <= $3), 'rows', coalesce(json_agg(s1.data ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $3), '[]'::json)) AS data
FROM (
  SELECT json_build_object('id', t0."id", 'location_x', CASE WHEN ST_GeometryType(t0."location") = 'ST_Point' THEN ST_X(t0."location") END, 'location_y', CASE WHEN ST_GeometryType(t0."location") = 'ST_Point' THEN ST_Y(t0."location") END, 'location_num_points', ST_NPoints(t0."location"), 'location_num_geometries', ST_NumGeometries(t0."location"), 'location_point_on_surface', ST_AsGeoJSON(ST_PointOnSurface(t0."location"))::json, 'location_wkt', ST_AsText(t0."location"), 'location_ewkt', ST_AsEWKT(t0."location"), 'location_is_empty', ST_IsEmpty(t0."location"), 'location_is_simple', ST_IsSimple(t0."location"), 'location_xmin', ST_XMin(t0."location"), 'location_ymin', ST_YMin(t0."location"), 'location_xmax', ST_XMax(t0."location"), 'location_ymax', ST_YMax(t0."location"), $1::text, CASE WHEN ST_GeometryType(ST_Transform(t0."location", 3857)) = 'ST_Point' THEN ST_X(ST_Transform(t0."location", 3857)) END, 'area_x', CASE WHEN ST_GeometryType(t0."area"::geometry) = 'ST_Point' THEN ST_X(t0."area"::geometry) END, 'area_z', CASE WHEN ST_GeometryType(t0."area"::geometry) = 'ST_Point' THEN ST_Z(t0."area"::geometry) END, 'area_m', CASE WHEN ST_GeometryType(t0."area"::geometry) = 'ST_Point' THEN ST_M(t0."area"::geometry) END, 'area_start_point', ST_AsGeoJSON(CASE WHEN ST_GeometryType(t0."area"::geometry) IN ('ST_LineString', 'ST_CircularString', 'ST_CompoundCurve') THEN ST_StartPoint(t0."area"::geometry) END)::json, 'area_end_point', ST_AsGeoJSON(CASE WHEN ST_GeometryType(t0."area"::geometry) IN ('ST_LineString', 'ST_CircularString', 'ST_CompoundCurve') THEN ST_EndPoint(t0."area"::geometry) END)::json, 'area_wkt', ST_AsText(ST_SimplifyPreserveTopology(t0."area"::geometry, $2))) AS data, jsonb_build_array(t0."id") AS __key, row_number() OVER (ORDER BY t0."id" ASC) AS __rn
  FROM "public"."places" t0
  ORDER BY t0."id" ASC
  LIMIT 6
) s1
-- args: ["mx",0.001,5]
